    assert.match(db, /^upload_queue_[a-f0-9]{32}$/); await queue.client.db(db).dropDatabase(); await queue.close(); await cleanup(dir);
  }
});

test('producer cancellation and timeout are durable; foreign tenant result cannot be read', { timeout: 15000 }, async () => {
  const dir = await temporary(), db = `upload_queue_${randomUUID().replaceAll('-', '')}`;
  const env = { ...process.env, UPLOAD_QUEUE_DB: db, UPLOAD_TENANT_ID: 'a', UPLOAD_ACTOR: 'operator', MONGODB_URL: process.env.MONGODB_URL ?? 'mongodb://127.0.0.1:27017' };
  const queue = await connectQueue(env);
  try {
    const abort = new AbortController(), transport = await createQueueTransport(queue, { spoolRoot: dir, runId: hash('cancel'), timeoutMs: 2000, signal: abort.signal, pollMs: 10 });
    const pending = transport(startRequest()); setTimeout(() => abort.abort(), 100);
    await assert.rejects(pending, /cancelled/);
    const row = await queue.jobs.findOne(queue.scope({ runId: hash('cancel') }));
    assert.equal(row.status, 'failed'); assert.ok(row.cancelledAt);
    const timeout = await createQueueTransport(queue, { spoolRoot: dir, runId: hash('timeout'), timeoutMs: 50, pollMs: 10 });
    await assert.rejects(timeout(startRequest()), /timeout/);
    const credentials = await createQueueTransport(queue, { spoolRoot: dir, runId: hash('credential'), timeoutMs: 100 });
    await assert.rejects(credentials({ ...startRequest(), body: { apiKey: 'body-secret' } }), /credential field/);
    assert.equal(await queue.jobs.countDocuments(queue.scope({ runId: hash('credential') })), 0);
    const foreign = await createQueueTransport(queue, { spoolRoot: dir, runId: hash('foreign'), timeoutMs: 2000, pollMs: 10 });
    const request = foreign(startRequest());
    let existing;
    for (let n = 0; n < 100 && !existing; n++) { existing = await queue.jobs.findOne(queue.scope({ runId: hash('foreign') })); if (!existing) await new Promise(r => setTimeout(r, 10)); }
    assert.ok(existing); await queue.jobs.deleteOne(queue.scope({ _id: existing._id }));
    await queue.jobs.insertOne({ ...existing, tenantId: 'foreign', status: 'done', response: { status: 200, headers: {}, body: { foreign: true } } });
    await assert.rejects(request, /operation missing/);
    assert.equal((await queue.jobs.findOne({ _id: existing._id, tenantId: 'foreign' })).status, 'done');
  } finally { assert.match(db, /^upload_queue_[a-f0-9]{32}$/); await queue.client.db(db).dropDatabase(); await queue.close(); await cleanup(dir); }
});

"""Restricted Gemini File API transport; credentials and upload capabilities stay in memory."""
import hashlib
import json
import os
import re
import stat
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

HOST = "generativelanguage.googleapis.com"
MAX_RESPONSE = 2 * 1024 * 1024


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def safe_file(root, reference, tenant):
    segment = hashlib.sha256(tenant.encode()).hexdigest()
    if not re.fullmatch(rf"{segment}/blobs/[a-f0-9]{{64}}\.bin", reference or ""):
        raise ValueError("unsafe-blob-reference")
    root = Path(root).absolute()
    path = root / reference
    parts = list(reversed(root.parents)) + [root]
    parts.extend(root.joinpath(*Path(reference).parts[:i]) for i in range(1, len(Path(reference).parts) + 1))
    for part in parts:
        info = part.lstat()
        if part.is_symlink() or getattr(info, "st_file_attributes", 0) & 0x400:
            raise ValueError("linked-blob-refused")
    actual = path.resolve(strict=True)
    actual.relative_to(root.resolve(strict=True))
    before = actual.stat()
    fd = os.open(actual, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        held = os.fstat(fd)
        if not stat.S_ISREG(held.st_mode) or held.st_nlink != 1 or (held.st_dev, held.st_ino) != (before.st_dev, before.st_ino):
            raise ValueError("blob-substitution")
        if path.resolve(strict=True) != actual:
            raise ValueError("blob-substitution")
        with os.fdopen(fd, "rb", closefd=False) as source:
            data = source.read(1024 * 1024 * 1024 + 1)
        after = os.fstat(fd)
        if len(data) > 1024 * 1024 * 1024 or (held.st_size, held.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
            raise ValueError("blob-changed-or-oversized")
        return data
    finally:
        os.close(fd)


def provider_url(url, operation):
    parsed = urllib.parse.urlsplit(url)
    if parsed.scheme != "https" or parsed.hostname != HOST or parsed.port or parsed.username or parsed.password or parsed.fragment:
        raise ValueError("unsupported-provider-boundary")
    allowed_query = {"upload_id", "upload_protocol"} if operation == "upload-finalize" else set()
    if set(urllib.parse.parse_qs(parsed.query)) - allowed_query:
        raise ValueError("secret-or-unsupported-query")
    paths = {"upload-start": r"/upload/v1beta/files", "upload-finalize": r"/upload/v1beta/files",
        "poll": r"/v1beta/files/[a-zA-Z0-9_-]+", "generate": r"/v1beta/models/[a-zA-Z0-9._-]+:generateContent"}
    if not re.fullmatch(paths.get(operation, r"(?!)"), parsed.path):
        raise ValueError("unsupported-provider-path")
    return url


class GoogleTransport:
    def __init__(self, queue, spool, api_key, timeout=1800):
        self.queue, self.spool, self.api_key, self.timeout = queue, spool, api_key, timeout
        self.uploads = {}
        self.opener = urllib.request.build_opener(NoRedirect())

    def _http(self, url, method, headers, body):
        if not self.api_key:
            raise ValueError("worker-provider-key-missing")
        headers = {**headers, "x-goog-api-key": self.api_key}
        request = urllib.request.Request(url, data=body, method=method, headers=headers)
        try:
            response = self.opener.open(request, timeout=self.timeout)
        except urllib.error.HTTPError as error:
            status = error.code
            error.close()
            return {"status": status, "headers": {}, "body": {"error": "provider-rejected-operation"}}
        with response:
            raw = response.read(MAX_RESPONSE + 1)
            if len(raw) > MAX_RESPONSE:
                raise ValueError("provider-response-oversized")
            try:
                body = json.loads(raw) if raw else None
            except (ValueError, UnicodeError):
                raise ValueError("provider-response-not-json")
            clean = json.dumps(body).replace(self.api_key, "[redacted]")
            result = {"status": response.status, "headers": {}, "body": json.loads(clean)}
            upload = response.headers.get("x-goog-upload-url")
            if upload:
                result["upload_url"] = provider_url(upload, "upload-finalize")
            return result

    def execute(self, doc):
        request = doc.get("request", {})
        if doc.get("tenantId") != self.queue.tenant or not re.fullmatch(r"[a-f0-9]{64}", doc.get("_id", "")) or not re.fullmatch(r"[a-f0-9]{64}", doc.get("runId", "")):
            raise ValueError("foreign-or-invalid-operation-identity")
        if len(json.dumps(request).encode()) > 128 * 1024:
            raise ValueError("operation-envelope-oversized")
        op, method = request.get("op"), request.get("method")
        expected = {"upload-start": "POST", "upload-finalize": "PUT", "poll": "GET", "generate": "POST"}
        if method != expected.get(op) or set(request) - {"op", "url", "method", "headers", "body"}:
            raise ValueError("unsupported-operation")
        headers = request.get("headers", {})
        allowed = {"upload-start": {"content-type", "x-goog-upload-protocol", "x-goog-upload-command", "x-goog-upload-header-content-length", "x-goog-upload-header-content-type"},
            "upload-finalize": {"x-goog-upload-offset", "x-goog-upload-command"}, "poll": set(), "generate": {"content-type"}}
        if not isinstance(headers, dict) or set(headers) - allowed[op] or any(not isinstance(v, str) or "\n" in v or "\r" in v for v in headers.values()):
            raise ValueError("unsupported-header")
        body = request.get("body")
        if op == "upload-finalize":
            matched = re.fullmatch(r"queue-upload://([a-f0-9]{64})", request.get("url", ""))
            if not matched or not isinstance(body, dict) or set(body) != {"blob", "sha256", "size"}:
                raise ValueError("invalid-upload-handoff")
            start_id = matched[1]
            expected_binding = (self.queue.tenant, doc["runId"], start_id, "upload-start")
            cached = self.uploads.get(start_id)
            if cached is not None and (not isinstance(cached, dict) or cached.get("binding") != expected_binding):
                raise ValueError("foreign-or-missing-upload-handoff")
            start = self.queue.collection.find_one(self.queue.scoped({"_id": start_id, "status": "done",
                "runId": doc["runId"], "request.op": "upload-start"}))
            if not start or start.get("tenantId") != self.queue.tenant or start.get("runId") != doc["runId"] or start.get("request", {}).get("op") != "upload-start":
                raise ValueError("foreign-or-missing-upload-handoff")
            if start_id not in self.uploads:
                # Restart recovery reopens this scoped start operation; no upload token is durable.
                self.execute(start)
            cached = self.uploads[start_id]
            if not isinstance(cached, dict) or cached.get("binding") != expected_binding:
                raise ValueError("foreign-or-missing-upload-handoff")
            url = provider_url(cached["url"], "upload-finalize")
            data = safe_file(self.spool, body["blob"], self.queue.tenant)
            if len(data) != body["size"] or hashlib.sha256(data).hexdigest() != body["sha256"]:
                raise ValueError("staged-blob-hash-mismatch")
            if headers != {"x-goog-upload-offset": "0", "x-goog-upload-command": "upload, finalize"}:
                raise ValueError("invalid-finalize-headers")
            self.uploads.pop(start_id)
        else:
            url = provider_url(request.get("url", ""), op)
            if op == "upload-start":
                if not isinstance(body, dict) or set(body) != {"file"} or not isinstance(body["file"], dict) or set(body["file"]) != {"display_name"}:
                    raise ValueError("invalid-upload-metadata")
                if not isinstance(body["file"]["display_name"], str) or len(body["file"]["display_name"]) > 200:
                    raise ValueError("invalid-upload-name")
                if headers.get("x-goog-upload-protocol") != "resumable" or headers.get("x-goog-upload-command") != "start" or headers.get("content-type") != "application/json":
                    raise ValueError("invalid-upload-headers")
                if not re.fullmatch(r"[0-9]{1,10}", headers.get("x-goog-upload-header-content-length", "")) or int(headers["x-goog-upload-header-content-length"]) > 1024**3:
                    raise ValueError("invalid-upload-size")
                if headers.get("x-goog-upload-header-content-type") not in {"audio/mp4", "video/mp4", "audio/mpeg", "audio/wav", "audio/ogg", "audio/webm", "video/webm"}:
                    raise ValueError("unsupported-media-type")
            elif op == "poll":
                if body is not None:
                    raise ValueError("poll-body-refused")
                name = urllib.parse.urlsplit(url).path.removeprefix("/v1beta/")
                if not self.queue.collection.find_one(self.queue.scoped({"status": "done", "runId": doc["runId"],
                    "request.op": "upload-finalize", "response.body.file.name": name})):
                    raise ValueError("foreign-or-missing-provider-file")
            elif op == "generate":
                if headers != {"content-type": "application/json"} or not isinstance(body, dict) or set(body) != {"contents", "generationConfig"}:
                    raise ValueError("invalid-generate-envelope")
                parts = body.get("contents", [{}])[0].get("parts", [])
                if len(body["contents"]) != 1 or len(parts) != 2 or set(parts[0]) != {"text"} or not isinstance(parts[0]["text"], str) or len(parts[0]["text"]) > 8000 or set(parts[1]) != {"fileData"}:
                    raise ValueError("invalid-generate-parts")
                file_data = parts[1]["fileData"]
                if set(file_data) != {"mimeType", "fileUri"} or file_data["mimeType"] != "audio/mp4":
                    raise ValueError("invalid-generate-file")
                provider_url(file_data["fileUri"], "poll")
                if not self.queue.collection.find_one(self.queue.scoped({"status": "done", "runId": doc["runId"],
                    "request.op": "upload-finalize", "response.body.file.uri": file_data["fileUri"]})):
                    raise ValueError("foreign-or-missing-provider-file")
                if body["generationConfig"] != {"thinkingConfig": {"thinkingBudget": 0}}:
                    raise ValueError("unsupported-generation-config")
            data = json.dumps(body).encode() if body is not None else None
        result = self._http(url, method, headers, data)
        if op == "upload-start" and 200 <= result["status"] < 300:
            upload_url = result.pop("upload_url", None)
            if not upload_url:
                raise ValueError("provider-upload-handoff-missing")
            self.uploads[doc["_id"]] = {"url": upload_url,
                "binding": (doc["tenantId"], doc["runId"], doc["_id"], "upload-start")}
            result["headers"] = {"x-goog-upload-url": f"queue-upload://{doc['_id']}"}
        else:
            result.pop("upload_url", None)
        if len(json.dumps(result).encode()) > MAX_RESPONSE:
            raise ValueError("provider-response-oversized")
        return result

"""Tenant-scoped atomic claims and fenced publication for the shared jobs collection."""
import time
import uuid
from datetime import datetime, timezone
from pymongo import ReturnDocument
from schema_check import validate_document


def now_ms():
    return int(time.time() * 1000)


def iso():
    return datetime.now(timezone.utc).isoformat()


class JobQueue:
    def __init__(self, collection, tenant, lease_ms=30000):
        if not isinstance(tenant, str) or not tenant.strip() or len(tenant) > 200:
            raise ValueError("trusted tenant configuration required")
        if not 100 <= lease_ms <= 300000:
            raise ValueError("invalid lease duration")
        self.collection, self.tenant, self.lease_ms = collection, tenant, lease_ms

    def scoped(self, query):
        return {**query, "tenantId": self.tenant, "kind": "transcribe.rpc"}

    def claim(self):
        now = now_ms()
        expired = self.scoped({"status": {"$in": ["pending", "processing"]}, "$or": [
            {"deadlineMs": {"$lte": now}},
            {"status": "processing", "leaseUntilMs": {"$lte": now}, "$expr": {"$gte": ["$attempts", "$maxAttempts"]}}]})
        self.collection.update_many(expired, {"$set": {"status": "failed", "error": "deadline-or-attempts-exhausted", "updatedAt": iso()}})
        query = self.scoped({"deadlineMs": {"$gt": now}, "cancelledAt": {"$exists": False},
            "$expr": {"$lt": ["$attempts", "$maxAttempts"]},
            "$or": [{"status": "pending"}, {"status": "processing", "leaseUntilMs": {"$lte": now}}]})
        token = uuid.uuid4().hex
        doc = self.collection.find_one_and_update(query, {"$set": {"status": "processing", "claimToken": token,
            "leaseUntilMs": now + self.lease_ms, "updatedAt": iso()}, "$inc": {"attempts": 1}},
            sort=[("createdAt", 1)], return_document=ReturnDocument.AFTER)
        if doc:
            try:
                validate_document("jobs", doc)
                if doc.get("maxAttempts") not in (1, 2) or not isinstance(doc.get("attempts"), int):
                    raise ValueError("invalid retry policy")
            except Exception:
                self.finish(doc, error="invalid-job-contract")
                return None
        return doc

    def owned(self, doc):
        return self.scoped({"_id": doc["_id"], "status": "processing", "claimToken": doc["claimToken"],
            "leaseUntilMs": {"$gt": now_ms()}, "deadlineMs": {"$gt": now_ms()}, "cancelledAt": {"$exists": False}})

    def heartbeat(self, doc):
        return self.collection.update_one(self.owned(doc), {"$set": {"leaseUntilMs": now_ms() + self.lease_ms}}).modified_count == 1

    def finish(self, doc, response=None, error=None):
        update = {"status": "failed" if error else "done", "updatedAt": iso()}
        if error:
            update["error"] = error[:120]
        else:
            update["response"] = response
        candidate = {**doc, **update}
        validate_document("jobs", candidate)
        return self.collection.update_one(self.owned(doc), {"$set": update, "$unset": {"claimToken": "", "leaseUntilMs": ""}}).modified_count == 1

    def release(self, doc):
        # Process shutdown leaves a bounded recoverable lease; an old owner stays fenced.
        return self.collection.update_one(self.owned(doc), {"$set": {"leaseUntilMs": now_ms() - 1}}).modified_count == 1

"""Validate documents against the repository's authoritative schemas, without logging data."""
import json
import sys
from pathlib import Path
from jsonschema import Draft202012Validator, FormatChecker

ROOT = Path(__file__).resolve().parents[3]


def validate_document(collection, document):
    if collection not in {"jobs", "sources", "sessions", "turns"}:
        raise ValueError("unsupported schema")
    schema = json.loads((ROOT / "schema" / f"{collection}.schema.json").read_text(encoding="utf-8"))
    Draft202012Validator(schema, format_checker=FormatChecker()).validate(document)


if __name__ == "__main__":
    try:
        payload = json.load(sys.stdin)
        for collection, documents in payload.items():
            for document in documents:
                validate_document(collection, document)
        print("schema-valid")
    except Exception:
        print("schema validation failed", file=sys.stderr)
        sys.exit(1)

// @lkb/transcribe is an isolated Python queue worker (D-003).
// Execute src/worker.py; this workspace marker intentionally exports no TS application logic.
export {};

{
  "name": "@lkb/transcribe",
  "version": "0.0.0",
  "private": true,
  "description": "Isolated Python Gemini transcription transport worker — communicates through tenant-scoped jobs only; see README.md for worker and file-submission commands."
}

/**
 * packages/ai/src/stt/gemini-file-upload.ts — T-003. The Gemini File API flow for audio too
 * large for `gemini.ts`'s inline-base64 path (most of the real TOC session recordings are
 * 20-60MB). Behind its own small `UploadTransport` seam — the shared `Transport` type in
 * `provider.ts` doesn't expose response headers, which the resumable-upload handoff needs (the
 * upload-start response returns the actual upload URL in an `x-goog-upload-url` header, not the
 * body) — a deliberate, narrow addition rather than widening the type every other adapter
 * depends on. No real network call anywhere in this module's own logic; a real implementation is
 * injected by the caller (a script, not a test).
 */
import type { Turn } from "./transcribe.js";

export interface UploadTransportRequest {
  method: string;
  url: string;
  headers?: Record<string, string>;
  /** JSON object (upload-start) or raw bytes (upload-finalize PUT). */
  body?: unknown;
}

export interface UploadTransportResponse {
  status: number;
  /** Lowercased header names. */
  headers: Record<string, string>;
  /** Parsed JSON body when the response is JSON; undefined otherwise. */
  body?: unknown;
}

export type UploadTransport = (req: UploadTransportRequest) => Promise<UploadTransportResponse>;

const DEFAULT_MODEL = "gemini-3.5-flash";

function assertOk(res: UploadTransportResponse, step: string): void {
  if (res.status < 200 || res.status >= 300) {
    throw new Error(`gemini file upload: ${step} failed with status ${res.status}: ${JSON.stringify(res.body)}`);
  }
}

/** Starts + finalizes a resumable file upload. Returns the uploaded file's `uri` (for
 * `generateContent`'s `fileData`) and `name` (for polling status). */
export async function uploadFile(bytes: Uint8Array, mimeType: string, transport: UploadTransport,
  apiKey: string, displayName = "audio"): Promise<{ fileUri: string; name: string }> {
  const start = await transport({
    method: "POST",
    url: `https://generativelanguage.googleapis.com/upload/v1beta/files?key=${apiKey}`,
    headers: {
      "X-Goog-Upload-Protocol": "resumable",
      "X-Goog-Upload-Command": "start",
      "X-Goog-Upload-Header-Content-Length": String(bytes.byteLength),
      "X-Goog-Upload-Header-Content-Type": mimeType,
      "Content-Type": "application/json",
    },
    body: { file: { display_name: displayName } },
  });
  assertOk(start, "upload-start");

  const uploadUrl = start.headers["x-goog-upload-url"];
  if (!uploadUrl) {
    throw new Error("gemini file upload: upload-start response carried no x-goog-upload-url header");
  }

  const finalize = await transport({
    method: "PUT",
    url: uploadUrl,
    headers: { "X-Goog-Upload-Offset": "0", "X-Goog-Upload-Command": "upload, finalize" },
    body: bytes,
  });
  assertOk(finalize, "upload-finalize");

  const body = finalize.body as { file?: { uri?: string; name?: string } } | undefined;
  if (!body?.file?.uri || !body.file.name) {
    throw new Error("gemini file upload: finalize response missing file.uri/file.name");
  }
  return { fileUri: body.file.uri, name: body.file.name };
}

export type FileState = "ACTIVE" | "FAILED" | "PROCESSING";

/** A SINGLE poll — the caller (a real script, never a test) retries with its own backoff. */
export async function pollFileState(name: string, transport: UploadTransport,
  apiKey: string): Promise<FileState> {
  const res = await transport({
    method: "GET",
    url: `https://generativelanguage.googleapis.com/v1beta/${name}?key=${apiKey}`,
  });
  assertOk(res, "poll-file-state");

  const body = res.body as { state?: string } | undefined;
  const state = body?.state;
  if (state === "ACTIVE" || state === "FAILED" || state === "PROCESSING") return state;
  throw new Error(`gemini file upload: unexpected file state "${String(state)}"`);
}

/** `hours` is `undefined` for a `[MM:SS]` match, or the parsed hour string for `[H:MM:SS]` —
 * real bug found live (2026-09-04): Gemini switches to the 3-group form once a transcript
 * crosses the 60-minute mark, which the original 2-group-only regex could not match at all,
 * silently absorbing everything past that point as unparsed trailing text glued onto the last
 * recognized turn. */
function parseTimestamp(hours: string | undefined, minutes: string, seconds: string): number {
  const h = hours !== undefined ? Number(hours) : 0;
  return h * 3600 + Number(minutes) * 60 + Number(seconds);
}

// Global, NOT anchored to line-start — real bug found live (2026-09-04): the model does not
// reliably put every `[MM:SS] Speaker:` marker on its own line; sometimes dozens of turns arrive
// back-to-back within one continuous block of text with no newline between them. A per-line
// regex silently swallowed everything after the first line-boundary-aligned marker into a single
// giant "turn" — the content wasn't lost (verified against a real response spanning a full
// ~60-minute session merged into 2 turns), just mis-split. Matching globally and slicing text
// between consecutive marker positions (not line boundaries) finds every real turn regardless of
// whether the model inserted a newline before it. Speaker capture is non-greedy up to a colon
// followed by whitespace ("<speaker>: text"), not just any colon — a speakerRef like "spk:1"
// contains its own colon with no following space, so a naive "first colon" split would wrongly
// cut it at "spk". The timestamp itself matches EITHER `[MM:SS]` (2 groups) OR `[H:MM:SS]`
// (3 groups, optional middle `(?:(\d{1,2}):)?` group) — see parseTimestamp's doc comment.
const TIMESTAMP_MARKER_RE = /\[(?:(\d{1,2}):)?(\d{1,2}):(\d{2})\]\s*(.+?):\s+/g;

/**
 * Parses `[MM:SS] SpeakerName: text` markers into `Turn[]` — matches anywhere in the text, not
 * just at line starts (see TIMESTAMP_MARKER_RE comment). `tEnd` for each turn is the NEXT turn's
 * `tStart`; the LAST turn's inferred `tEnd` is its own `tStart + 30` seconds, limited by a
 * finite positive media duration when its start precedes that duration. Unknown duration and
 * starts at/after EOF retain the fallback for downstream validation. Text before the first marker
 * (headers, preamble) is dropped; text between two markers belongs entirely to the FIRST one's
 * turn (it is that speaker's continued content, not a separate unparseable line to discard).
 */
// Real bug found live (2026-09-04, T-003 phase 4): the non-greedy `(.+?):\s+` speaker capture
// occasionally has no real "Name:"/"spk:N:" marker immediately after a timestamp to anchor on
// (the model continued straight into prose without one) and instead runs on until it happens to
// find SOME unrelated ": " later in that sentence -- swallowing real spoken content into
// `speakerRef` (observed: a real session's turn 2 had a ~280-character sentence fragment as its
// "speaker label"). A genuine speaker label (a name, a title, "spk:N") is never that long, so an
// implausibly long capture is treated as a mis-split: the swallowed text is recovered into the
// turn's own content (prepended, since it's real spoken words, not a label) and the speaker is
// inherited from the previous turn (the far more common case here is the same speaker
// continuing, not a genuine unlabeled speaker change).
const MAX_PLAUSIBLE_SPEAKER_LABEL_LENGTH = 60;

export function parseDiarizedTranscript(text: string, mediaDurationSeconds?: number): Turn[] {
  const matches = [...text.matchAll(TIMESTAMP_MARKER_RE)];
  const parsed: { speakerRef: string; tStart: number; text: string }[] = [];
  let lastPlausibleSpeaker = "spk:0";

  for (let i = 0; i < matches.length; i++) {
    const match = matches[i]!;
    const [, hours, mm, ss, speaker] = match;
    const contentStart = match.index + match[0].length;
    const contentEnd = i + 1 < matches.length ? matches[i + 1]!.index : text.length;
    let turnText = text.slice(contentStart, contentEnd).trim();
    let speakerRef = speaker!.trim();

    if (speakerRef.length >= MAX_PLAUSIBLE_SPEAKER_LABEL_LENGTH) {
      turnText = `${speakerRef}: ${turnText}`.trim();
      speakerRef = lastPlausibleSpeaker;
    } else {
      lastPlausibleSpeaker = speakerRef;
    }

    if (!turnText) continue;
    parsed.push({ speakerRef, tStart: parseTimestamp(hours, mm!, ss!), text: turnText });
  }

  const LAST_TURN_FALLBACK_SECONDS = 30;
  const knownDuration = Number.isFinite(mediaDurationSeconds) && mediaDurationSeconds! > 0;
  return parsed.map((turn, i) => ({
    speakerRef: turn.speakerRef,
    tStart: turn.tStart,
    tEnd: i + 1 < parsed.length ? parsed[i + 1]!.tStart
      : knownDuration && turn.tStart < mediaDurationSeconds!
        ? Math.min(turn.tStart + LAST_TURN_FALLBACK_SECONDS, mediaDurationSeconds!)
        : turn.tStart + LAST_TURN_FALLBACK_SECONDS,
    text: turn.text,
  }));
}

export interface TranscribeUploadedResult {
  turns: Turn[];
  usage: { inputTokens: number; outputTokens: number };
}

const DIARIZE_PROMPT = [
  "Transcribe and diarize this audio in full, start to end.",
  "Output ONLY the transcript as one line per turn, in this EXACT format:",
  "[MM:SS] SpeakerName: spoken text",
  "Use the speaker's actual name if it is said aloud or clearly inferable from context;",
  "otherwise use spk:0, spk:1, etc. consistently for the same voice.",
  // Real bug found live (2026-09-04): without this, one speaker talking continuously for
  // several minutes came back as ONE turn with a single leading marker and no others -- the
  // downstream parser's only way to guess that turn's real tEnd (the next marker's tStart, or
  // this +30s fallback for the very last turn) then drastically understated how much real
  // content/time it actually covered, making a fully-transcribed passage look like it stopped
  // after 30 seconds. Forcing a fresh marker at least every ~20s, even mid-monologue, keeps
  // tEnd accurate throughout instead of relying on speaker changes that may never come.
  "Insert a fresh [MM:SS] marker at least every 15-20 seconds even when the same speaker keeps",
  "talking without interruption -- never let one turn span more than about 20 seconds.",
  "No headers, no summary, no commentary outside the transcript lines.",
].join(" ");

/** Calls `generateContent` against an already-uploaded file (criterion 1's `uploadFile`). */
export async function transcribeUploadedAudio(fileUri: string, transport: UploadTransport,
  apiKey: string, model: string = DEFAULT_MODEL, mediaDurationSeconds?: number): Promise<TranscribeUploadedResult> {
  if (mediaDurationSeconds !== undefined && (!Number.isFinite(mediaDurationSeconds) || mediaDurationSeconds <= 0)) {
    throw new Error("gemini file upload: invalid measured media duration");
  }
  const res = await transport({
    method: "POST",
    url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
    headers: { "content-type": "application/json" },
    body: {
      contents: [
        {
          parts: [
            { text: DIARIZE_PROMPT },
            { fileData: { mimeType: "audio/mp4", fileUri } },
          ],
        },
      ],
      // Real bug found live (2026-09-04): without this, Gemini 2.5+/3.x's extended-thinking mode
      // can consume the entire output budget on hidden reasoning tokens, returning
      // `finishReason: "STOP"` with a near-empty transcript (`text: "\n"` plus an opaque
      // `thoughtSignature` blob) — a "successful" completion with no usable content. Disabling
      // thinking frees the whole budget for the actual transcript.
      generationConfig: { thinkingConfig: { thinkingBudget: 0 } },
    },
  });
  assertOk(res, "generateContent");

  const body = res.body as {
    candidates?: { content?: { parts?: { text?: string }[] }; finishReason?: string }[];
    promptFeedback?: { blockReason?: string };
    usageMetadata?: { promptTokenCount?: number; candidatesTokenCount?: number };
  } | undefined;
  const text = (body?.candidates?.[0]?.content?.parts ?? []).map((p) => p.text ?? "").join("");

  // A 200 response with no usable text is NOT a valid "silent recording" result — real audio
  // never legitimately transcribes to nothing. Caught live on a 62.7MB file: the model returned
  // finishReason (e.g. MAX_TOKENS/SAFETY/RECITATION) with an empty completion, and a naive caller
  // silently wrote 0 turns over 107 real placeholder turns before this guard existed. Throw with
  // the diagnostic fields so the caller knows WHY, rather than treating empty as success.
  if (text.trim().length === 0) {
    const finishReason = body?.candidates?.[0]?.finishReason;
    const blockReason = body?.promptFeedback?.blockReason;
    throw new Error(
      `gemini file upload: generateContent returned no usable text (finishReason=${finishReason ?? "unknown"}, ` +
      `blockReason=${blockReason ?? "none"}) — audio may be too long for a single call, or was blocked/truncated`,
    );
  }

  return {
    turns: parseDiarizedTranscript(text, mediaDurationSeconds),
    usage: {
      inputTokens: body?.usageMetadata?.promptTokenCount ?? 0,
      outputTokens: body?.usageMetadata?.candidatesTokenCount ?? 0,
    },
  };
}

/**
 * packages/ai/src/stt/gemini-file-upload.test.ts — T-003 C4. `uploadFile`, `pollFileState`,
 * `transcribeUploadedAudio`, `parseDiarizedTranscript` against a fake `UploadTransport` — no
 * real network call anywhere.
